"""Archive only build directories generated by this assigned task, preserving artifact bytes."""
from pathlib import Path
import hashlib,json,shutil,uuid
root=Path.cwd().resolve()
assert root==Path('H:/.codex/worktrees/st/IM-platform').resolve()
private=Path('H:/IM-platform/.git/worktrees/IM-platform43/state-runtime')
out=private/('final-build-artifacts-'+str(uuid.uuid4()));out.mkdir()
owned=['clients/mobile/.gradle','clients/mobile/app/build','clients/desktop/dist','clients/desktop/node_modules','clients/shared/protocol-sdk/node_modules','clients/shared/protocol-sdk/dist']
hashes={}
for rel in ['clients/mobile/app/build/outputs/apk/debug/app-debug.apk','clients/mobile/app/build/outputs/apk/androidTest/debug/app-debug-androidTest.apk']:
    p=root/rel;hashes[rel]=hashlib.sha256(p.read_bytes()).hexdigest()
rows=[]
for rel in owned:
    p=root/rel
    assert p.resolve().is_relative_to(root) and not p.is_symlink()
    if not p.exists():continue
    dest=out/rel;dest.parent.mkdir(parents=True,exist_ok=True)
    assert dest.resolve().is_relative_to(private.resolve()) and not dest.exists()
    shutil.move(str(p),str(dest));rows.append({'source':rel,'archive':str(dest),'removed':not p.exists()})
Path('spec/progress/evidence/LOOP1-CLIENT-STATE-001/final-generated-archive.json').write_text(json.dumps({'ownedOnly':True,'archive':str(out),'artifactSHA256':hashes,'directories':rows,'operation':'Only generated registered build outputs moved, no application data/preferences/credentials/unknown source'},indent=2)+'\n',encoding='utf-8')
print('PASS archived only task-owned build outputs and exact final APK hashes')
